ALTER TABLE "credit_buckets" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "credit_ownerships" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "voucher_ownerships" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "tenant_isolation_credit_buckets" ON "credit_buckets" AS PERMISSIVE FOR ALL TO "authenticated" USING (exists (select 1 from "credit_ownerships" join "organization_end_users" on "organization_end_users"."id" = "credit_ownerships"."organization_end_user_id" where "credit_ownerships"."id" = "credit_buckets"."credit_ownership_id" and "organization_end_users"."organization_id"::text = coalesce(current_setting('app.current_tenant_id', true), (current_setting('request.jwt.claims', true)::jsonb ->> 'tenant_id'))));--> statement-breakpoint
CREATE POLICY "tenant_isolation_credit_ownerships" ON "credit_ownerships" AS PERMISSIVE FOR ALL TO "authenticated" USING (exists (select 1 from "organization_end_users" where "organization_end_users"."id" = "credit_ownerships"."organization_end_user_id" and "organization_end_users"."organization_id"::text = coalesce(current_setting('app.current_tenant_id', true), (current_setting('request.jwt.claims', true)::jsonb ->> 'tenant_id'))));--> statement-breakpoint
CREATE POLICY "tenant_isolation_voucher_ownerships" ON "voucher_ownerships" AS PERMISSIVE FOR ALL TO "authenticated" USING (exists (select 1 from "organization_end_users" where "organization_end_users"."id" = "voucher_ownerships"."organization_end_user_id" and "organization_end_users"."organization_id"::text = coalesce(current_setting('app.current_tenant_id', true), (current_setting('request.jwt.claims', true)::jsonb ->> 'tenant_id'))));